import type { RequestHandler } from "@builder.io/qwik-city";
import { db, broker } from "../../../../../lib/state";

export const onPost: RequestHandler = async (requestEvent) => {
  const room = requestEvent.params.room;
  if (!room || !/^[A-Za-z0-9_-]+$/.test(room)) {
    requestEvent.json(400, { error: "Invalid room name" });
    return;
  }

  let body: any;
  try {
    body = await requestEvent.request.json();
  } catch (e) {
    requestEvent.json(400, { error: "Malformed or missing JSON body" });
    return;
  }

  if (!body || typeof body !== "object" || Array.isArray(body)) {
    requestEvent.json(400, { error: "Request body must be a JSON object" });
    return;
  }

  if (typeof body.user !== "string") {
    requestEvent.json(400, { error: "User must be a string" });
    return;
  }

  if (typeof body.text !== "string") {
    requestEvent.json(400, { error: "Text must be a string" });
    return;
  }

  const trimmedUser = body.user.trim();
  const trimmedText = body.text.trim();

  if (trimmedUser.length < 1 || trimmedUser.length > 64) {
    requestEvent.json(400, { error: "User must be between 1 and 64 characters" });
    return;
  }

  if (trimmedText.length < 1 || trimmedText.length > 2000) {
    requestEvent.json(400, { error: "Text must be between 1 and 2000 characters" });
    return;
  }

  const ts = Date.now();
  let seq: number;

  try {
    const result = db.transaction(() => {
      const insertStmt = db.prepare(`
        INSERT INTO messages (room, seq, user, text, ts)
        VALUES (
          ?,
          (SELECT COALESCE(MAX(seq), 0) + 1 FROM messages WHERE room = ?),
          ?,
          ?,
          ?
        )
        RETURNING seq
      `);
      return insertStmt.get(room, room, trimmedUser, trimmedText, ts) as { seq: number };
    })();
    seq = result.seq;
  } catch (err: any) {
    requestEvent.json(500, { error: err.message || "Database error" });
    return;
  }

  const message = {
    room,
    seq,
    user: trimmedUser,
    text: trimmedText,
    ts,
  };

  broker.publish(room, message);

  requestEvent.json(201, {
    room: message.room,
    seq: message.seq,
    user: message.user,
    text: message.text,
    ts: message.ts,
  });
};

import type { RequestHandler } from "@builder.io/qwik-city";
import { db, broker, type Message, type Subscriber } from "../../../../../lib/state";

export const onGet: RequestHandler = async (requestEvent) => {
  const room = requestEvent.params.room;
  if (!room || !/^[A-Za-z0-9_-]+$/.test(room)) {
    requestEvent.json(400, { error: "Invalid room name" });
    return;
  }

  // Set SSE headers
  requestEvent.status(200);
  requestEvent.headers.set("Content-Type", "text/event-stream");
  requestEvent.headers.set("Cache-Control", "no-cache, no-transform");
  requestEvent.headers.set("Connection", "keep-alive");

  const writableStream = requestEvent.getWritableStream();
  const writer = writableStream.getWriter();
  const encoder = new TextEncoder();

  let active = true;
  let cleanedUp = false;

  const subscriberId = Math.random().toString(36).substring(2);

  const cleanup = () => {
    if (cleanedUp) return;
    cleanedUp = true;
    active = false;
    broker.unsubscribe(room, sub);
    try {
      writer.close().catch(() => {});
    } catch (e) {}
  };

  requestEvent.signal.addEventListener("abort", cleanup);

  async function writeMessageToSSE(msg: Message) {
    if (!active) return;
    const jsonStr = JSON.stringify({
      room: msg.room,
      seq: msg.seq,
      user: msg.user,
      text: msg.text,
      ts: msg.ts,
    });
    const data = `id: ${msg.seq}\nevent: message\ndata: ${jsonStr}\n\n`;
    try {
      await writer.write(encoder.encode(data));
    } catch (err) {
      cleanup();
    }
  }

  const sub: Subscriber = {
    id: subscriberId,
    room,
    send: (msg) => {
      if (sub.isReplaying) {
        sub.queue.push(msg);
      } else {
        if (msg.seq > sub.highestSentSeq) {
          sub.highestSentSeq = msg.seq;
          writeMessageToSSE(msg).catch(() => {});
        }
      }
    },
    queue: [],
    isReplaying: true,
    highestSentSeq: -1,
  };

  // 1. Subscribe to broker
  broker.subscribe(room, sub);

  // 2. Parse Last-Event-ID
  const lastEventIdHeader = requestEvent.request.headers.get("last-event-id");
  let lastEventId: number | null = null;
  if (lastEventIdHeader !== null) {
    const parsed = parseInt(lastEventIdHeader, 10);
    if (!isNaN(parsed)) {
      lastEventId = parsed;
    }
  }

  sub.highestSentSeq = lastEventId !== null ? lastEventId : -1;

  // 3. Fetch history
  let history: Message[] = [];
  try {
    if (lastEventId !== null) {
      history = db.prepare(`
        SELECT room, seq, user, text, ts
        FROM messages
        WHERE room = ? AND seq > ?
        ORDER BY seq ASC
      `).all(room, lastEventId) as Message[];
    } else {
      const descHistory = db.prepare(`
        SELECT room, seq, user, text, ts
        FROM messages
        WHERE room = ?
        ORDER BY seq DESC
        LIMIT 50
      `).all(room) as Message[];
      history = descHistory.reverse();
    }
  } catch (err) {
    cleanup();
    return;
  }

  // 4. Send history
  for (const msg of history) {
    if (msg.seq > sub.highestSentSeq) {
      sub.highestSentSeq = msg.seq;
      await writeMessageToSSE(msg);
    }
  }

  // 5. Send queued live messages
  sub.isReplaying = false;
  const queued = [...sub.queue];
  sub.queue = [];
  for (const msg of queued) {
    if (msg.seq > sub.highestSentSeq) {
      sub.highestSentSeq = msg.seq;
      await writeMessageToSSE(msg);
    }
  }

  // Keep connection open until client aborts
  await new Promise<void>((resolve) => {
    requestEvent.signal.addEventListener("abort", () => {
      cleanup();
      resolve();
    });
  });
};

